" type="checkbox" ${strictAssets?'checked':''}> Sprawdź także obrazy i zasoby</label><p class="notice">Opcja zasobów dotyczy zestawu „Widoki po aktualizacji”.</p><p class="notice">Środowisko: <strong>${esc(state.configuration.target||'Nieskonfigurowane')}</strong><br>Testy uruchamiają się po zalogowaniu do CMS.</p><button id="run" class="primary" ${!selected.size||state.active||state.configuration.missing.length||launching?'disabled':''}>▷ Uruchom wybrane (${selected.size})</button><p class="notice">${state.active?'Trwa uruchomienie. Poczekaj na wynik.':'Wybierz pojedynczy scenariusz lub cały zestaw.'}</p></aside></div>${runDetail(active||state.history.find(r=>r.id===detailId))}`;return;}
 if(current==='history'){content.innerHTML=historyTable(state.history)+runDetail(state.history.find(r=>r.id===detailId)||active);return;}
