  if(!e)return '';
  const changes=items=>items?.length?'<ul>'+items.map(d=>`<li>${esc(d.field)}: ${esc(d.before)} → ${esc(d.after)}</li>`).join('')+'</ul>':'<p>Nie wykryto zmian w porównywanych polach.</p>';
  let html=/^[a-z0-9-]+\/raport\.html$/.test(e.report??'')?`<p><b>Dowody źródłowe tej kontroli:</b> <a href="${esc(e.report)}">Raport modułu z tego przebiegu</a> (tabele, wzorce, żądania i ewentualne dokumenty).</p>`:'';
  if(e.authentication)html+=`<p><b>Kontrola uwierzytelnienia:</b> oczekiwane HTTP ${esc(e.authentication.expectedStatuses.join('/'))}, faktyczne HTTP ${esc(e.authentication.actualStatus)}.</p>`;
  if(e.completionComparison){const d=e.completionComparison;html+=`<h4>Podsumowanie a zapis — trzy stany</h4><p>Kwoty w groszach. Numer zapisanego zamówienia: ${esc(d.orderNumber??'brak')} · HTTP complete: ${esc(d.status)}</p><table><tr><th>Etap</th><th>Rabat %</th><th>Produkty brutto</th><th>Do zapłaty</th><th>Netto</th></tr>${[['Przed obcym żądaniem',d.before],['Po obcym żądaniu',d.afterForeign],['Po finalizacji',d.saved]].map(([label,o])=>`<tr><td>${esc(label)}</td>${['rebatePercent','itemsTotal','total','totalNet'].map(key=>`<td>${esc(o[key]??'brak danych')}</td>`).join('')}</tr>`).join('')}</table><h4>Zmiany po obcym żądaniu</h4>${changes(e.isolation?.changes)}<h4>Zapis względem prawidłowego stanu początkowego</h4>${changes(d.changes)}<p>${esc(d.limit)}</p>`;}
  if(e.repeatComplete){const d=e.repeatComplete;html+=`<p><b>Drugie complete:</b> HTTP ${esc(d.actualStatus)}, oczekiwane ${esc(d.expectedStatuses.join('/'))}. Numer przed: ${esc(d.numberBefore)}, po: ${esc(d.numberAfter)}.</p>${changes(d.changes)}<p>${esc(d.limit)}</p>`;}
  if(e.measurements?.length)html+=`<details><summary>Dane przypadku: koszyk, produkty, waga i koszty</summary><pre>${esc(JSON.stringify(e.measurements,null,2))}</pre></details>`;
  if(/^[a-z0-9_-]+$/.test(e.sourceReportId??''))html+=`<p>Wykonanie tej kontroli: <a href="../${esc(e.sourceReportId)}/raport.html">raport próby źródłowej</a>.</p>`;
  return html;
}
function renderObservationTable(rows){
  if(!rows?.length)return '';
  const heads=['Etap','Koszyk','Produkt','Sztuki','Rabat %','Netto / szt. (gr)','Brutto pozycji (gr)','Dostawa brutto (gr)','Dostawa netto (gr)','Paczki'];
  return `<p><b>Pomiary tego przypadku:</b> kwoty w groszach, np. 1575 = 15,75 zł.</p><div style="overflow:auto"><table><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v??'brak danych')}</td>`).join('')}</tr>`).join('')}</table></div>`;
}
