  if(report.issue===36944)profile={title:'Redmine #36944 — ceny netto i brutto',purpose:'Cztery oddzielne kontrole 1 i 6 sztuk w WHOLESALE oraz RETAIL, przy 18,40 zł brutto, VAT 5% i rabacie/promocji 23%.',source:'Wymaganie #36944: 13,49 zł netto za 1 sztukę i 84,99 zł brutto za 6 sztuk bez dostawy. Oferta płatności WHOLESALE i niezależna konfiguracja promocji CMS RETAIL. Test nie wyznacza wzorca z odpowiedzi API.'};
  if(report.issue===36944&&report.apiOnlyWholesale)profile={title:'Redmine #36944 — API nowej hurtowni',purpose:'Dwie kontrole WHOLESALE: 1 i 6 sztuk produktu za 18,40 zł brutto, VAT 5%, rabat hurtownika 23%. Wyłącznie API; bez operacji CMS i finalizacji.',source:'Jawne oczekiwania użytkownika: 13,49 zł netto dla 1 sztuki i 84,99 zł brutto produktów dla 6 sztuk. Faktycznie dostępna płatność WHOLESALE z rabatem 23%. Dostawa poza wzorcem produktów.'};
  if(kind==='redmine-36926'){
    const status=report.reference?.checkoutSuccessStatus??201;
