export function renderReportExplanation(report,kind='order'){
  const g=buildReportExplanation(report,kind);
  const groups=[...new Set(g.cases.map(c=>c.category))].map(category=>{const cases=g.cases.filter(c=>c.category===category);return {category,pass:cases.filter(c=>c.status==='PASS').length,fail:cases.filter(c=>c.status==='FAIL').length,skip:cases.filter(c=>c.status==='SKIP').length};});
  const failures=g.cases.filter(c=>c.status==='FAIL');
